{
  "name": "God's Hand School Management System",
  "description": "A comprehensive school management portal featuring a student admission system, fee management, and an administrative dashboard for the proprietor.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  GUEST = 'GUEST',
  STUDENT = 'STUDENT',
  ADMIN = 'ADMIN'
}

export type GradeLevel = 
  | 'KG 1' | 'KG 2'
  | 'Nursery 1' | 'Nursery 2'
  | 'Primary 1' | 'Primary 2' | 'Primary 3' | 'Primary 4' | 'Primary 5'
  | 'JSS 1' | 'JSS 2' | 'JSS 3'
  | 'SSS 1' | 'SSS 2' | 'SSS 3';

export interface FeeStructure {
  [key: string]: number;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
}

export interface StudentApplication {
  id: string;
  name: string;
  email: string;
  grade: GradeLevel;
  paid: boolean;
  timestamp: string;
}

export interface AppState {
  fees: FeeStructure;
  announcements: Announcement[];
  applications: StudentApplication[];
}

import { AppState } from '../types';
import { INITIAL_FEES, APP_STORAGE_KEY } from '../constants';

const DEFAULT_STATE: AppState = {
  fees: INITIAL_FEES,
  announcements: [
    {
      id: '1',
      title: 'Welcome to the New Session',
      content: 'We are excited to welcome all students back to campus. God is our strength!',
      date: new Date().toLocaleDateString()
    }
  ],
  applications: []
};

export const stateService = {
  getState: (): AppState => {
    const saved = localStorage.getItem(APP_STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to parse state", e);
      }
    }
    return DEFAULT_STATE;
  },

  saveState: (state: AppState): void => {
    localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(state));
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserRole, AppState, GradeLevel, StudentApplication, Announcement } from './types';
import { stateService } from './services/stateService';
import { GRADE_GROUPS } from './constants';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { AdminPanel } from './components/AdminPanel';
import { StudentPortal } from './components/StudentPortal';
import { Footer } from './components/Footer';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [state, setState] = useState<AppState>(stateService.getState());
  const [view, setView] = useState<'home' | 'portal' | 'apply' | 'admin'>('home');

  // Sync state to local storage whenever it changes
  useEffect(() => {
    stateService.saveState(state);
  }, [state]);

  const updateFees = (grade: string, amount: number) => {
    setState(prev => ({
      ...prev,
      fees: { ...prev.fees, [grade]: amount }
    }));
  };

  const addAnnouncement = (title: string, content: string) => {
    const newAnn: Announcement = {
      id: Date.now().toString(),
      title,
      content,
      date: new Date().toLocaleDateString()
    };
    setState(prev => ({
      ...prev,
      announcements: [newAnn, ...prev.announcements]
    }));
  };

  const submitApplication = (app: Omit<StudentApplication, 'id' | 'timestamp' | 'paid'>) => {
    const newApp: StudentApplication = {
      ...app,
      id: 'APP-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      paid: true
    };
    setState(prev => ({
      ...prev,
      applications: [newApp, ...prev.applications]
    }));
    return newApp;
  };

  return (
    <div className="min-h-screen flex flex-col font-sans">
      <Header 
        role={role} 
        setRole={setRole} 
        setView={setView} 
        activeView={view} 
      />

      <main className="flex-grow">
        {view === 'home' && (
          <Hero 
            announcements={state.announcements} 
            onApply={() => setView('apply')}
          />
        )}

        {view === 'apply' && (
          <div className="max-w-4xl mx-auto py-12 px-4">
            <StudentPortal 
              fees={state.fees} 
              onSubmit={submitApplication} 
              onBack={() => setView('home')} 
            />
          </div>
        )}

        {view === 'portal' && (
          <div className="max-w-4xl mx-auto py-12 px-4 text-center">
            <div className="bg-white p-12 rounded-2xl shadow-xl border border-blue-50">
                <h2 className="text-3xl font-bold text-blue-900 mb-4">Student Portal</h2>
                <p className="text-slate-600 mb-8">Access your learning materials and results.</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <button className="p-8 bg-blue-50 text-blue-700 rounded-xl hover:bg-blue-100 transition-colors">
                        <span className="block text-4xl mb-2">📚</span>
                        <span className="font-semibold">My Courses</span>
                    </button>
                    <button className="p-8 bg-indigo-50 text-indigo-700 rounded-xl hover:bg-indigo-100 transition-colors">
                        <span className="block text-4xl mb-2">📝</span>
                        <span className="font-semibold">Exam Results</span>
                    </button>
                </div>
            </div>
          </div>
        )}

        {view === 'admin' && role === UserRole.ADMIN && (
          <div className="max-w-6xl mx-auto py-12 px-4">
            <AdminPanel 
              fees={state.fees} 
              applications={state.applications}
              announcements={state.announcements}
              onUpdateFee={updateFees}
              onAddAnnouncement={addAnnouncement}
            />
          </div>
        )}

        {view === 'admin' && role !== UserRole.ADMIN && (
          <div className="flex flex-col items-center justify-center py-20">
            <h2 className="text-2xl font-bold text-red-600">Access Denied</h2>
            <p className="text-slate-500">Please login as Administrator to view this page.</p>
            <button 
              onClick={() => setRole(UserRole.ADMIN)}
              className="mt-4 px-6 py-2 bg-blue-900 text-white rounded-lg"
            >
              Simulate Admin Login
            </button>
          </div>
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React from 'react';
import { UserRole } from '../types';

interface HeaderProps {
  role: UserRole;
  setRole: (role: UserRole) => void;
  setView: (view: 'home' | 'portal' | 'apply' | 'admin') => void;
  activeView: string;
}

export const Header: React.FC<HeaderProps> = ({ role, setRole, setView, activeView }) => {
  return (
    <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20">
          <div 
            className="flex items-center cursor-pointer" 
            onClick={() => setView('home')}
          >
            <div className="w-12 h-12 bg-blue-900 rounded-full flex items-center justify-center text-white text-2xl font-bold mr-3">
              GHS
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-900 leading-tight">God's Hand School</h1>
              <p className="text-xs text-blue-700 font-semibold tracking-wider uppercase">Excellence in God's Service</p>
            </div>
          </div>

          <nav className="hidden md:flex space-x-8">
            <button 
              onClick={() => setView('home')}
              className={`text-sm font-medium transition-colors ${activeView === 'home' ? 'text-blue-700' : 'text-slate-600 hover:text-blue-900'}`}
            >
              Home
            </button>
            <button 
              onClick={() => setView('apply')}
              className={`text-sm font-medium transition-colors ${activeView === 'apply' ? 'text-blue-700' : 'text-slate-600 hover:text-blue-900'}`}
            >
              Admissions
            </button>
            <button 
              onClick={() => setView('portal')}
              className={`text-sm font-medium transition-colors ${activeView === 'portal' ? 'text-blue-700' : 'text-slate-600 hover:text-blue-900'}`}
            >
              Student Portal
            </button>
            {role === UserRole.ADMIN && (
              <button 
                onClick={() => setView('admin')}
                className={`text-sm font-medium transition-colors ${activeView === 'admin' ? 'text-blue-700' : 'text-slate-600 hover:text-blue-900'}`}
              >
                Proprietor Panel
              </button>
            )}
          </nav>

          <div className="flex items-center space-x-4">
            {role === UserRole.GUEST ? (
              <div className="flex space-x-2">
                <button 
                  onClick={() => { setRole(UserRole.STUDENT); setView('portal'); }}
                  className="px-4 py-2 text-sm font-medium text-blue-900 border border-blue-900 rounded-lg hover:bg-blue-50 transition-all"
                >
                  Student Login
                </button>
                <button 
                  onClick={() => { setRole(UserRole.ADMIN); setView('admin'); }}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-900 rounded-lg hover:bg-blue-800 transition-all"
                >
                  Admin Login
                </button>
              </div>
            ) : (
              <button 
                onClick={() => { setRole(UserRole.GUEST); setView('home'); }}
                className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-red-600 transition-all"
              >
                Logout
              </button>
            )}
          </div>
        </div>
      </div>
    </header>
  );
};

import React, { useState } from 'react';
import { FeeStructure, StudentApplication, Announcement, GradeLevel } from '../types';
import { GRADE_GROUPS } from '../constants';

interface AdminPanelProps {
  fees: FeeStructure;
  applications: StudentApplication[];
  announcements: Announcement[];
  onUpdateFee: (grade: string, amount: number) => void;
  onAddAnnouncement: (title: string, content: string) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  fees, 
  applications, 
  announcements,
  onUpdateFee,
  onAddAnnouncement
}) => {
  const [activeTab, setActiveTab] = useState<'fees' | 'applications' | 'announcements'>('fees');
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');

  const handleAnnSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (annTitle && annContent) {
      onAddAnnouncement(annTitle, annContent);
      setAnnTitle('');
      setAnnContent('');
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100">
      <div className="bg-blue-900 px-8 py-10 text-white">
        <h2 className="text-3xl font-bold mb-2">Proprietor's Dashboard</h2>
        <p className="text-blue-100 opacity-80">Oversee the academic and financial health of God's Hand School.</p>
      </div>

      <div className="flex border-b border-slate-200">
        <button 
          onClick={() => setActiveTab('fees')}
          className={`px-8 py-4 font-semibold text-sm transition-all ${activeTab === 'fees' ? 'text-blue-700 border-b-2 border-blue-700 bg-blue-50/50' : 'text-slate-500 hover:text-slate-800'}`}
        >
          Fee Management
        </button>
        <button 
          onClick={() => setActiveTab('applications')}
          className={`px-8 py-4 font-semibold text-sm transition-all ${activeTab === 'applications' ? 'text-blue-700 border-b-2 border-blue-700 bg-blue-50/50' : 'text-slate-500 hover:text-slate-800'}`}
        >
          Student Admissions ({applications.length})
        </button>
        <button 
          onClick={() => setActiveTab('announcements')}
          className={`px-8 py-4 font-semibold text-sm transition-all ${activeTab === 'announcements' ? 'text-blue-700 border-b-2 border-blue-700 bg-blue-50/50' : 'text-slate-500 hover:text-slate-800'}`}
        >
          Communication
        </button>
      </div>

      <div className="p-8">
        {activeTab === 'fees' && (
          <div className="space-y-8">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-900">Configure Academic Fees</h3>
              <p className="text-xs text-slate-500 italic">Changes reflect instantly for new applicants.</p>
            </div>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
              {GRADE_GROUPS.map(group => (
                <div key={group.name} className="bg-slate-50 rounded-2xl p-6 border border-slate-200">
                  <h4 className="font-bold text-blue-900 mb-4 border-b border-blue-100 pb-2">{group.name} Levels</h4>
                  <div className="space-y-4">
                    {group.levels.map(level => (
                      <div key={level} className="flex items-center justify-between group">
                        <label className="text-sm font-medium text-slate-600">{level}</label>
                        <div className="relative">
                          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">₦</span>
                          <input 
                            type="number" 
                            value={fees[level]}
                            onChange={(e) => onUpdateFee(level, parseInt(e.target.value) || 0)}
                            className="pl-8 pr-4 py-2 w-32 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-900 focus:ring-2 focus:ring-blue-500 transition-all outline-none"
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'applications' && (
          <div>
            <h3 className="text-xl font-bold text-slate-900 mb-6">Recent Admission Forms (Paid)</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b border-slate-200 text-slate-500 text-sm">
                    <th className="pb-4 font-semibold">Date</th>
                    <th className="pb-4 font-semibold">Student Name</th>
                    <th className="pb-4 font-semibold">Grade</th>
                    <th className="pb-4 font-semibold">Reference</th>
                    <th className="pb-4 font-semibold">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {applications.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-20 text-center text-slate-400">No applications received yet.</td>
                    </tr>
                  ) : (
                    applications.map(app => (
                      <tr key={app.id} className="hover:bg-slate-50 transition-colors">
                        <td className="py-4 text-sm text-slate-600">{new Date(app.timestamp).toLocaleDateString()}</td>
                        <td className="py-4 font-bold text-slate-900">{app.name}</td>
                        <td className="py-4 text-sm text-blue-700 font-semibold">{app.grade}</td>
                        <td className="py-4 text-xs font-mono text-slate-500">{app.id}</td>
                        <td className="py-4">
                          <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold uppercase">Paid</span>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'announcements' && (
          <div className="grid lg:grid-cols-3 gap-12">
            <div className="lg:col-span-1">
              <h3 className="text-xl font-bold text-slate-900 mb-6">Post New Update</h3>
              <form onSubmit={handleAnnSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Title</label>
                  <input 
                    type="text" 
                    value={annTitle}
                    onChange={(e) => setAnnTitle(e.target.value)}
                    placeholder="e.g. Mid-term Break Notice"
                    className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Content</label>
                  <textarea 
                    rows={6}
                    value={annContent}
                    onChange={(e) => setAnnContent(e.target.value)}
                    placeholder="Provide details for parents and students..."
                    className="w-full px-4 py-2 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <button 
                  type="submit"
                  className="w-full py-3 bg-blue-900 text-white font-bold rounded-xl hover:bg-blue-800 transition-all shadow-lg shadow-blue-900/10"
                >
                  Publish Announcement
                </button>
              </form>
            </div>

            <div className="lg:col-span-2">
              <h3 className="text-xl font-bold text-slate-900 mb-6">History</h3>
              <div className="space-y-4">
                {announcements.map(ann => (
                  <div key={ann.id} className="p-6 border border-slate-200 rounded-2xl">
                    <div className="flex justify-between items-start mb-2">
                      <h4 className="font-bold text-slate-900">{ann.title}</h4>
                      <span className="text-xs text-slate-400 font-medium">{ann.date}</span>
                    </div>
                    <p className="text-slate-600 text-sm whitespace-pre-wrap">{ann.content}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { FeeStructure, GradeLevel } from '../types';
import { GRADE_GROUPS } from '../constants';

interface StudentPortalProps {
  fees: FeeStructure;
  onSubmit: (app: { name: string, email: string, grade: GradeLevel }) => any;
  onBack: () => void;
}

export const StudentPortal: React.FC<StudentPortalProps> = ({ fees, onSubmit, onBack }) => {
  const [step, setStep] = useState<'form' | 'payment' | 'success'>('form');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [grade, setGrade] = useState<GradeLevel>('Primary 1');
  const [refId, setRefId] = useState('');

  const handleApply = (e: React.FormEvent) => {
    e.preventDefault();
    if (name && email && grade) {
      setStep('payment');
    }
  };

  const handlePayment = () => {
    // Simulate payment processing
    const result = onSubmit({ name, email, grade });
    setRefId(result.id);
    setStep('success');
  };

  return (
    <div className="max-w-2xl mx-auto">
      {step === 'form' && (
        <div className="bg-white rounded-3xl shadow-xl p-8 border border-blue-50">
          <button onClick={onBack} className="text-slate-400 hover:text-blue-900 flex items-center mb-8 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Back to Home
          </button>

          <div className="text-center mb-10">
            <h2 className="text-3xl font-bold text-slate-900 mb-3">Admission Application</h2>
            <p className="text-slate-500">Fill the form below to initiate your application process.</p>
          </div>

          <form onSubmit={handleApply} className="space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Student Full Name</label>
                <input 
                  type="text" 
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  placeholder="John Doe"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Parent Email Address</label>
                <input 
                  type="email" 
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  placeholder="parent@example.com"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Selecting Grade Level</label>
              <select 
                value={grade}
                onChange={(e) => setGrade(e.target.value as GradeLevel)}
                className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all appearance-none bg-slate-50"
              >
                {GRADE_GROUPS.map(group => (
                  <optgroup key={group.name} label={group.name}>
                    {group.levels.map(level => (
                      <option key={level} value={level}>{level}</option>
                    ))}
                  </optgroup>
                ))}
              </select>
            </div>

            <div className="p-4 bg-blue-50 rounded-xl border border-blue-100 flex justify-between items-center">
              <span className="text-blue-900 font-medium">Application Fee:</span>
              <span className="text-xl font-bold text-blue-900">₦{fees[grade].toLocaleString()}</span>
            </div>

            <button 
              type="submit"
              className="w-full py-4 bg-blue-900 text-white font-bold rounded-xl shadow-lg shadow-blue-900/20 hover:bg-blue-800 transition-all transform hover:-translate-y-1"
            >
              Continue to Payment
            </button>
          </form>
        </div>
      )}

      {step === 'payment' && (
        <div className="bg-white rounded-3xl shadow-xl p-10 border border-blue-50 text-center">
          <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
            </svg>
          </div>
          <h2 className="text-3xl font-bold text-slate-900 mb-4">Payment Summary</h2>
          <div className="max-w-xs mx-auto text-left space-y-3 mb-10">
            <div className="flex justify-between text-slate-600">
              <span>Student:</span>
              <span className="font-bold text-slate-900">{name}</span>
            </div>
            <div className="flex justify-between text-slate-600">
              <span>Grade:</span>
              <span className="font-bold text-slate-900">{grade}</span>
            </div>
            <div className="border-t border-slate-100 pt-3 flex justify-between text-blue-900">
              <span className="font-bold">Total Payable:</span>
              <span className="font-extrabold text-2xl">₦{fees[grade].toLocaleString()}</span>
            </div>
          </div>

          <p className="text-sm text-slate-500 mb-8 px-6">
            Clicking pay will simulate a secure transaction. In a production environment, you would be redirected to a payment gateway like Paystack or Flutterwave.
          </p>

          <div className="space-y-4">
            <button 
              onClick={handlePayment}
              className="w-full py-4 bg-green-600 text-white font-bold rounded-xl shadow-lg shadow-green-600/20 hover:bg-green-700 transition-all"
            >
              Pay Now (₦{fees[grade].toLocaleString()})
            </button>
            <button 
              onClick={() => setStep('form')}
              className="w-full py-4 text-slate-500 font-bold hover:text-slate-800 transition-all"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {step === 'success' && (
        <div className="bg-white rounded-3xl shadow-xl p-12 border border-blue-50 text-center animate-in fade-in zoom-in duration-500">
          <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-8">
