    e.preventDefault();
    if (name && email && grade) {
      setStep('payment');
    }
  };

  const handlePayment = () => {
    // Simulate payment processing
    const result = onSubmit({ name, email, grade });
    setRefId(result.id);
    setStep('success');
  };

  return (
    <div className="max-w-2xl mx-auto">
      {step === 'form' && (
        <div className="bg-white rounded-3xl shadow-xl p-8 border border-purple-50">
          <button onClick={onBack} className="text-slate-400 hover:text-purple-900 flex items-center mb-8 transition-colors font-bold">
