  }, [state]);

  const updateFees = (grade: string, amount: number) => {
    setState(prev => ({
      ...prev,
      fees: { ...prev.fees, [grade]: amount }
    }));
  };

  const addAnnouncement = (title: string, content: string) => {
    const newAnn: Announcement = {
      id: Date.now().toString(),
      title,
      content,
      date: new Date().toLocaleDateString()
    };
    setState(prev => ({
      ...prev,
      announcements: [newAnn, ...prev.announcements]
    }));
  };

  const addCourse = (name: string, grade: GradeLevel, description: string) => {
    const newCourse: Course = {
      id: 'CRS-' + Date.now(),
      name,
      grade,
      description
    };
    setState(prev => ({
      ...prev,
      courses: [...prev.courses, newCourse]
    }));
  };

  const submitApplication = (app: Omit<StudentApplication, 'id' | 'timestamp' | 'paid'>) => {
    const newApp: StudentApplication = {
      ...app,
      id: 'APP-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      paid: true
    };
    setState(prev => ({
      ...prev,
      applications: [newApp, ...prev.applications]
    }));
    return newApp;
  };

  const createTeacherAccount = (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => {
    const newTeacher: TeacherAccount = {
      ...teacher,
      id: 'TEA-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      teachers: [...prev.teachers, newTeacher]
    }));
  };

  const handleAdminLoginAttempt = (password: string) => {
    // Check Admin
    if (password === '197005') {
      setRole(UserRole.ADMIN);
      setCurrentUser('Proprietor');
      setAdminError('');
      return;
    } 

    // Check Teachers
    const teacher = state.teachers.find(t => t.password === password);
    if (teacher) {
      setRole(UserRole.TEACHER);
      setCurrentUser(teacher.username);
      setView('teacher');
      setAdminError('');
      return;
    }

    setAdminError('Invalid security key. Access denied.');
  };

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50">
      <Header 
        role={role} 
        setRole={setRole} 
        setView={setView} 
        activeView={view} 
      />

      <main className="flex-grow">
        {view === 'home' && (
          <Hero 
            announcements={state.announcements} 
            onApply={() => setView('apply')}
          />
        )}

        {view === 'apply' && (
          <div className="max-w-4xl mx-auto py-12 px-4">
            <StudentPortal 
              fees={state.fees} 
              onSubmit={submitApplication} 
              onBack={() => setView('home')} 
            />
          </div>
        )}

        {view === 'portal' && (
          <div className="max-w-4xl mx-auto py-12 px-4 text-center">
            <div className="bg-white p-12 rounded-2xl shadow-xl border border-yellow-400">
                <h2 className="text-3xl font-bold text-blue-900 mb-4">Student Portal</h2>
                <p className="text-slate-600 mb-8">Access your learning materials and check your results here.</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <button className="p-8 bg-blue-900 text-white rounded-xl hover:bg-blue-800 transition-all flex flex-col items-center">
                        <span className="block text-4xl mb-2 text-yellow-400">📚</span>
                        <span className="font-semibold">My Courses</span>
                    </button>
                    <button className="p-8 bg-yellow-400 text-blue-900 rounded-xl hover:bg-yellow-500 transition-all flex flex-col items-center">
                        <span className="block text-4xl mb-2">📝</span>
                        <span className="font-semibold">My Results</span>
                    </button>
                </div>

                <div className="mt-12 text-left">
                  <h3 className="text-xl font-bold text-blue-900 mb-4">Curriculum Overview</h3>
                  <div className="grid grid-cols-1 gap-4">
                    {state.courses.map(course => (
                      <div key={course.id} className="p-4 border border-slate-100 rounded-lg flex justify-between items-center bg-slate-50">
                        <div>
                          <p className="font-bold text-blue-900">{course.name}</p>
                          <p className="text-xs text-slate-500">{course.description}</p>
                        </div>
                        <span className="text-[10px] font-black uppercase bg-blue-100 text-blue-800 px-2 py-1 rounded">{course.grade}</span>
                      </div>
                    ))}
                  </div>
                </div>
            </div>
          </div>
        )}

        {view === 'teacher' && role === UserRole.TEACHER && (
           <div className="max-w-6xl mx-auto py-12 px-4">
             <TeacherDashboard 
               username={currentUser || 'Staff'} 
               courses={state.courses}
               results={state.results}
               onAddCourse={addCourse}
             />
           </div>
        )}

        {view === 'admin' && (
          role === UserRole.ADMIN ? (
            <div className="max-w-6xl mx-auto py-12 px-4">
              <AdminPanel 
                fees={state.fees} 
                applications={state.applications}
                announcements={state.announcements}
                teachers={state.teachers}
                results={state.results}
                courses={state.courses}
                onUpdateFee={updateFees}
                onAddAnnouncement={addAnnouncement}
                onCreateTeacher={createTeacherAccount}
                onAddCourse={addCourse}
              />
            </div>
          ) : (
            <AdminLoginGateway 
              onLogin={handleAdminLoginAttempt}
              onBack={() => setView('home')}
              error={adminError}
            />
          )
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

