                    className={`w-full pl-14 pr-6 py-4 bg-slate-50 border-2 rounded-2xl font-black text-xl tracking-widest text-center text-blue-900 focus:ring-4 focus:ring-blue-900/10 focus:bg-white outline-none transition-all shadow-inner ${error ? 'border-red-300' : 'border-slate-100 focus:border-blue-900'}`}
                  />
                </div>
                {error && (
                  <div className="flex items-center justify-center text-red-600 font-black text-[10px] uppercase tracking-widest mt-3 animate-bounce">
                    <span className="mr-1">⚠️</span> {error}
                  </div>
                )}
              </div>

              <button 
                type="submit"
                className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-xl rounded-2xl shadow-xl hover:bg-blue-800 transition-all transform hover:-translate-y-1 active:scale-95 flex items-center justify-center group"
              >
                <span>Proprietor Access</span>
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 ml-2 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" />
                </svg>
              </button>

              <button 
                type="button"
                onClick={onBack}
                className="w-full py-4 text-slate-400 font-black text-xs uppercase tracking-widest hover:text-blue-900 transition-colors"
              >
                Return to Campus Home
              </button>
            </form>
          </div>

          <div className="bg-slate-50 px-10 py-6 text-center border-t-2 border-slate-100">
            <p className="text-[10px] text-slate-400 font-bold uppercase leading-relaxed">
              Proprietor: God's Hand School<br/>
              <span className="text-blue-900 font-black">Have Faith In God</span>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

