  | 'Nursery 1' | 'Nursery 2'
  | 'Primary 1' | 'Primary 2' | 'Primary 3' | 'Primary 4' | 'Primary 5'
  | 'JSS 1' | 'JSS 2' | 'JSS 3'
  | 'SSS 1' | 'SSS 2' | 'SSS 3';

export interface FeeStructure {
  [key: string]: number;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
}

export interface Course {
  id: string;
  name: string;
  grade: GradeLevel;
  description: string;
}

export interface StudentApplication {
  id: string;
  name: string;
  email: string;
  grade: GradeLevel;
  paid: boolean;
  timestamp: string;
}

export interface TeacherAccount {
  id: string;
  username: string;
  password: string;
  createdAt: string;
  assignedGrades: GradeLevel[];
  assignedCourses: string[]; // Array of Course IDs
}

export interface StudentAccount {
  id: string;
  name: string;
  email: string;
  password: string;
  grade: GradeLevel;
  createdAt: string;
}

export interface StudentResult {
  id: string;
  studentName: string;
  grade: GradeLevel;
  subject: string;
  score: number;
  term: string;
  teacherName: string;
  date: string;
}

export interface AppState {
  fees: FeeStructure;
  announcements: Announcement[];
  applications: StudentApplication[];
  teachers: TeacherAccount[];
  studentAccounts: StudentAccount[];
  results: StudentResult[];
  courses: Course[];
}

