                  className={`flex items-center space-x-2 px-4 py-2 rounded-xl text-sm font-black uppercase tracking-widest transition-all border-2 ${isMenuOpen ? 'bg-blue-900 text-yellow-400 border-blue-900 shadow-lg' : 'text-blue-900 border-slate-100 hover:border-blue-900 hover:bg-slate-50'}`}
                >
                  <span>Home</span>
                  <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
                  </svg>
                </button>

                {isMenuOpen && (
                  <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border-2 border-slate-100 overflow-hidden py-2 animate-in slide-in-from-top-2 duration-200">
                    <div className="px-4 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 mb-2">Navigation</div>
                    {menuItems.map(item => (
                      <button 
                        key={item.label}
                        onClick={() => navigateTo(item.view as any)}
                        className={`w-full text-left px-5 py-3 text-sm font-bold flex items-center transition-all ${activeView === item.view ? 'bg-blue-50 text-blue-900' : 'text-slate-600 hover:bg-slate-50 hover:text-blue-900'}`}
                      >
                        <span className="mr-3 text-lg">{item.icon}</span>
                        {item.label}
                      </button>
                    ))}

                    {role === UserRole.TEACHER && (
                      <button 
                        onClick={() => navigateTo('teacher')}
                        className={`w-full text-left px-5 py-3 text-sm font-bold flex items-center transition-all border-t border-slate-50 mt-2 ${activeView === 'teacher' ? 'bg-yellow-50 text-blue-900' : 'text-blue-700 hover:bg-yellow-50'}`}
                      >
                        <span className="mr-3 text-lg">📁</span>
                        Dashboard
                      </button>
                    )}

                    {role === UserRole.ADMIN && (
                      <button 
                        onClick={() => navigateTo('admin')}
                        className={`w-full text-left px-5 py-3 text-sm font-bold flex items-center transition-all border-t border-slate-50 mt-2 ${activeView === 'admin' ? 'bg-yellow-50 text-blue-900' : 'text-blue-700 hover:bg-yellow-50'}`}
                      >
                        <span className="mr-3 text-lg">⚙️</span>
                        Proprietor Panel
                      </button>
                    )}
                  </div>
                )}
              </div>

              <div className="h-8 w-0.5 bg-slate-100 hidden sm:block"></div>

              {role === UserRole.GUEST ? (
                <div className="flex items-center space-x-2">
                  <button 
                    onClick={() => navigateTo('studentAuth')}
                    className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-white bg-blue-900 rounded-xl hover:bg-blue-800 transition-all shadow-md active:scale-95"
                  >
                    Login
                  </button>
                  <button 
                    onClick={() => navigateTo('admin')}
                    className="p-2 text-blue-900 bg-yellow-400 rounded-full hover:shadow-lg transition-all"
                    title="Proprietor Login"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 md:h-6 md:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                    </svg>
                  </button>
                </div>
              ) : (
                <div className="flex items-center space-x-2">
                  <div className="hidden lg:flex flex-col items-end mr-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{role} MODE</span>
                  </div>
                  <button 
                    onClick={() => { setRole(UserRole.GUEST); navigateTo('home'); }}
                    className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-red-600 border-2 border-red-50 rounded-xl hover:bg-red-50 hover:border-red-100 transition-all"
                  >
                    Logout
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>
    </div>
  );
};

import React, { useState } from 'react';
import { FeeStructure, StudentApplication, Announcement, TeacherAccount, StudentResult, Course, GradeLevel } from '../types';
import { GRADE_GROUPS } from '../constants';

interface AdminPanelProps {
  fees: FeeStructure;
  applications: StudentApplication[];
  announcements: Announcement[];
  teachers: TeacherAccount[];
  results: StudentResult[];
  courses: Course[];
  calendar: string;
  onUpdateFee: (grade: string, amount: number) => void;
  onAddAnnouncement: (title: string, content: string) => void;
  onCreateTeacher: (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => void;
  onAddCourse: (name: string, grade: GradeLevel, description: string) => void;
  onUpdateCalendar: (content: string) => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  fees, 
  applications, 
  announcements,
  teachers,
  results,
  courses,
  calendar,
  onUpdateFee,
  onAddAnnouncement,
  onCreateTeacher,
  onAddCourse,
  onUpdateCalendar
}) => {
  const [activeTab, setActiveTab] = useState<'fees' | 'applications' | 'announcements' | 'teachers' | 'results' | 'courses' | 'calendar'>('fees');

  // Announcement states
  const [annTitle, setAnnTitle] = useState('');
  const [annContent, setAnnContent] = useState('');

  // Teacher states
  const [teacherUser, setTeacherUser] = useState('');
  const [teacherPass, setTeacherPass] = useState('');
  const [assignedGrades, setAssignedGrades] = useState<GradeLevel[]>([]);
  const [assignedCourses, setAssignedCourses] = useState<string[]>([]);

  // Course states
  const [courseName, setCourseName] = useState('');
  const [courseGrade, setCourseGrade] = useState<GradeLevel>('Primary 1');
  const [courseDesc, setCourseDesc] = useState('');

  // Calendar state
  const [tempCalendar, setTempCalendar] = useState(calendar);

  const toggleGrade = (g: GradeLevel) => {
    setAssignedGrades(prev => prev.includes(g) ? prev.filter(item => item !== g) : [...prev, g]);
  };

  const toggleCourse = (id: string) => {
    setAssignedCourses(prev => prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]);
  };

  const handleTeacherSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherUser && teacherPass) {
      onCreateTeacher({ 
        username: teacherUser, 
        password: teacherPass,
        assignedGrades,
        assignedCourses
      });
      setTeacherUser('');
      setTeacherPass('');
      setAssignedGrades([]);
      setAssignedCourses([]);
      alert("Staff account created with assigned classes and subjects!");
    }
  };

  const handleCourseSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (courseName) {
      onAddCourse(courseName, courseGrade, courseDesc);
      setCourseName('');
      setCourseDesc('');
      alert("Course added successfully!");
    }
  };

  const handleAnnSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (annTitle && annContent) {
      onAddAnnouncement(annTitle, annContent);
      setAnnTitle('');
      setAnnContent('');
      alert("Bulletin posted successfully!");
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-blue-900">
      <div className="bg-blue-900 px-10 py-12 text-white relative">
        <div className="absolute top-0 right-0 p-10 opacity-10">
          <svg className="w-48 h-48" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08 1.99 0 5.97 1.09 6 3.08-1.29 1.94-3.5 3.22-6 3.22z"/></svg>
        </div>
        <div className="relative z-10">
          <h2 className="text-4xl font-black mb-3 font-serif">Proprietor's Dashboard</h2>
          <div className="flex items-center space-x-4">
            <span className="px-3 py-1 bg-yellow-400 text-blue-900 rounded-lg text-xs font-black uppercase tracking-tighter shadow-md">Academic Session 2025</span>
            <p className="text-blue-100 font-medium">Control center for God's Hand School management.</p>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap border-b-2 border-slate-100 bg-slate-50">
        {[
          { id: 'fees', label: 'Fees Config' },
          { id: 'applications', label: 'Admissions' },
          { id: 'teachers', label: 'Staff' },
          { id: 'courses', label: 'Courses' },
          { id: 'calendar', label: 'Calendar' },
          { id: 'announcements', label: 'Bulletins' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-5 font-black text-sm uppercase tracking-widest transition-all ${activeTab === tab.id ? 'text-blue-900 border-b-4 border-blue-900 bg-white' : 'text-slate-400 hover:text-blue-700 hover:bg-slate-100'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="p-10">
        {activeTab === 'fees' && (
          <div className="space-y-10">
            <div className="flex justify-between items-end border-b-2 border-slate-100 pb-6">
              <div>
                <h3 className="text-2xl font-black text-blue-900 mb-2 font-serif">Academic Fee Structure</h3>
                <p className="text-slate-500 font-medium">Configure the session amounts for each grade level.</p>
              </div>
            </div>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-10">
              {GRADE_GROUPS.map(group => (
                <div key={group.name} className="bg-slate-50/30 rounded-3xl p-8 border-2 border-blue-100/50">
                  <h4 className="font-black text-blue-900 text-lg mb-6 flex items-center">{group.name}</h4>
                  <div className="space-y-6">
                    {group.levels.map(level => (
                      <div key={level} className="flex flex-col space-y-2">
                        <label className="text-xs font-black text-slate-400 uppercase tracking-widest">{level}</label>
                        <div className="relative">
                          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-900 font-black">₦</span>
                          <input 
                            type="number" 
                            value={fees[level]}
                            onChange={(e) => onUpdateFee(level, parseInt(e.target.value) || 0)}
                            className="pl-10 pr-4 py-4 w-full bg-white border-2 border-blue-100 rounded-2xl text-lg font-black text-blue-900 outline-none shadow-sm"
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'calendar' && (
            <div className="space-y-8 max-w-2xl">
                <h3 className="text-2xl font-black text-blue-900 font-serif">Manage Academic Calendar</h3>
                <p className="text-slate-500 font-medium">Provide schedule information or school updates that will appear on the Home screen.</p>
                <div className="space-y-4">
                    <textarea 
                        value={tempCalendar}
                        onChange={(e) => setTempCalendar(e.target.value)}
                        rows={10}
                        className="w-full px-6 py-4 bg-slate-50 border-2 border-blue-100 rounded-3xl font-bold text-blue-900 outline-none focus:bg-white shadow-inner"
                        placeholder="1. Jan 10th - Resumption..."
                    />
                    <button 
                        onClick={() => { onUpdateCalendar(tempCalendar); alert("Calendar updated!"); }}
                        className="px-10 py-5 bg-blue-900 text-yellow-400 font-black rounded-2xl shadow-xl hover:bg-blue-800 transition-all"
                    >
                        Save Calendar Changes
                    </button>
                </div>
            </div>
        )}

        {activeTab === 'teachers' && (
          <div className="grid lg:grid-cols-2 gap-16">
            <div className="space-y-10">
              <h3 className="text-2xl font-black text-blue-900 font-serif">Staff Management</h3>
              <form onSubmit={handleTeacherSubmit} className="space-y-8 bg-slate-50 p-10 rounded-[2.5rem] border-2 border-slate-100">
                <div className="grid sm:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Staff Username</label>
                    <input 
                      type="text" required value={teacherUser}
                      onChange={(e) => setTeacherUser(e.target.value)}
                      placeholder="e.g. benson_j"
                      className="w-full px-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold focus:ring-4 focus:ring-blue-100 outline-none transition-all shadow-sm"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Pass-key</label>
                    <input 
                      type="password" required value={teacherPass}
                      onChange={(e) => setTeacherPass(e.target.value)}
                      placeholder="••••••••"
                      className="w-full px-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold focus:ring-4 focus:ring-blue-100 outline-none transition-all shadow-sm"
                    />
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-xs font-black text-blue-900 uppercase tracking-widest px-1">Assign Classes (Grades)</label>
                  <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 max-h-40 overflow-y-auto p-4 bg-white rounded-2xl border-2 border-slate-100 custom-scrollbar">
                    {GRADE_GROUPS.flatMap(g => g.levels).map(lvl => (
                      <button
                        key={lvl} type="button"
                        onClick={() => toggleGrade(lvl as GradeLevel)}
                        className={`px-2 py-2 rounded-lg text-[10px] font-black uppercase transition-all border-2 ${assignedGrades.includes(lvl as GradeLevel) ? 'bg-blue-900 text-yellow-400 border-blue-900 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-50 hover:border-blue-200'}`}
                      >
                        {lvl}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-xs font-black text-blue-900 uppercase tracking-widest px-1">Assign Subject Courses</label>
                  <div className="max-h-60 overflow-y-auto p-4 bg-white rounded-2xl border-2 border-slate-100 custom-scrollbar space-y-2">
                    {courses.length === 0 ? (
                      <p className="text-[10px] text-slate-400 font-bold uppercase text-center py-4">Add courses first in the Courses tab</p>
                    ) : (
                      courses.map(course => (
                        <div key={course.id} className="flex items-center space-x-3 p-3 rounded-xl hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100">
                          <input 
                            type="checkbox" id={course.id} 
                            checked={assignedCourses.includes(course.id)}
                            onChange={() => toggleCourse(course.id)}
                            className="w-5 h-5 rounded border-2 border-slate-200 text-blue-900 focus:ring-blue-900"
                          />
                          <label htmlFor={course.id} className="flex-1 cursor-pointer">
                            <p className="text-sm font-black text-blue-900">{course.name}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{course.grade}</p>
                          </label>
                        </div>
                      ))
                    )}
                  </div>
                </div>

                <button 
                  type="submit"
                  className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all transform hover:-translate-y-1"
                >
                  Register Staff Account
                </button>
              </form>
            </div>

            <div>
              <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Staff Directory</h3>
              <div className="space-y-6">
                {teachers.length === 0 ? (
                  <div className="p-12 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">No staff on record</div>
                ) : (
                  teachers.map(teacher => (
                    <div key={teacher.id} className="p-6 bg-white rounded-3xl border-2 border-slate-50 shadow-sm hover:border-blue-100 transition-all">
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center">
                          <div className="w-12 h-12 bg-blue-100 text-blue-900 rounded-xl flex items-center justify-center font-black mr-4 text-xl">
                            {teacher.username.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <p className="font-black text-blue-900 text-lg">{teacher.username}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Joined {new Date(teacher.createdAt).toLocaleDateString()}</p>
                          </div>
                        </div>
                        <button className="text-red-500 font-black text-[10px] uppercase tracking-widest hover:bg-red-50 px-3 py-1 rounded-lg transition-colors">Deactivate</button>
                      </div>

                      <div className="space-y-3 pt-4 border-t border-slate-50">
                        <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1.5">Classes:</p>
                          <div className="flex flex-wrap gap-1.5">
                            {teacher.assignedGrades.length > 0 ? teacher.assignedGrades.map(g => (
                              <span key={g} className="px-2 py-0.5 bg-blue-50 text-blue-700 text-[9px] font-black rounded uppercase border border-blue-100">{g}</span>
                            )) : <span className="text-[9px] text-slate-300 italic font-bold">Unassigned</span>}
                          </div>
                        </div>
                        <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1.5">Subjects:</p>
                          <div className="flex flex-wrap gap-1.5">
                            {teacher.assignedCourses.length > 0 ? teacher.assignedCourses.map(id => {
                              const c = courses.find(item => item.id === id);
                              return c ? (
                                <span key={id} className="px-2 py-0.5 bg-yellow-50 text-yellow-700 text-[9px] font-black rounded uppercase border border-yellow-100">{c.name}</span>
                              ) : null;
                            }) : <span className="text-[9px] text-slate-300 italic font-bold">Unassigned</span>}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'applications' && (
          <div className="space-y-8">
            <h3 className="text-2xl font-black text-blue-900 font-serif text-nowrap">Admission Forms Received</h3>
            <div className="bg-white rounded-[2rem] border-2 border-slate-100 overflow-x-auto shadow-sm">
              <table className="w-full text-left min-w-[600px]">
                <thead>
                  <tr className="bg-slate-50 text-slate-400 text-xs font-black uppercase tracking-widest">
                    <th className="px-8 py-6">Timestamp</th>
                    <th className="px-8 py-6">Applicant</th>
                    <th className="px-8 py-6">Grade</th>
                    <th className="px-8 py-6">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y-2 divide-slate-50">
                  {applications.length === 0 ? (
                    <tr><td colSpan={4} className="py-24 text-center text-slate-300 font-bold uppercase tracking-widest text-xs">No entries found</td></tr>
                  ) : (
                    applications.map(app => (
                      <tr key={app.id} className="hover:bg-blue-50/30 transition-colors">
                        <td className="px-8 py-6 text-sm text-slate-500 font-medium">{new Date(app.timestamp).toLocaleString()}</td>
                        <td className="px-8 py-6">
                          <p className="font-black text-blue-900">{app.name}</p>
                          <p className="text-xs text-slate-400">{app.email}</p>
                        </td>
                        <td className="px-8 py-6">
                          <span className="px-3 py-1 bg-yellow-100 text-blue-700 rounded-lg text-[10px] font-black uppercase tracking-tighter">{app.grade}</span>
                        </td>
                        <td className="px-8 py-6">
                          <div className="flex items-center text-green-600 font-black text-xs uppercase tracking-widest">Verified</div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'courses' && (
          <div className="grid lg:grid-cols-2 gap-16">
            <div>
              <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Add Academic Course</h3>
              <form onSubmit={handleCourseSubmit} className="space-y-6 bg-slate-50 p-10 rounded-[2.5rem] border-2 border-slate-100">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Subject Name</label>
                  <input type="text" required value={courseName} onChange={(e) => setCourseName(e.target.value)} className="w-full px-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold text-slate-900 outline-none" placeholder="e.g. Further Mathematics" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Grade Level</label>
                  <select value={courseGrade} onChange={(e) => setCourseGrade(e.target.value as GradeLevel)} className="w-full px-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold text-slate-900 outline-none">
                    {GRADE_GROUPS.flatMap(g => g.levels).map(lvl => <option key={lvl} value={lvl}>{lvl}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest px-1">Description</label>
                  <textarea value={courseDesc} onChange={(e) => setCourseDesc(e.target.value)} rows={3} className="w-full px-6 py-4 bg-white border-2 border-slate-200 rounded-2xl font-bold text-slate-900 outline-none" placeholder="Course objectives..." />
                </div>
                <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all">Save Course</button>
              </form>
            </div>
            <div className="space-y-6">
               <h3 className="text-2xl font-black text-blue-900 font-serif">Global Curriculum</h3>
               <div className="max-h-[600px] overflow-y-auto pr-4 custom-scrollbar space-y-4">
                 {courses.map(course => (
                   <div key={course.id} className="p-6 bg-white border-2 border-slate-50 rounded-2xl shadow-sm hover:border-blue-100 transition-all">
                     <div className="flex justify-between items-start mb-2">
                       <h4 className="font-black text-blue-900 text-lg font-serif">{course.name}</h4>
                       <span className="text-[10px] font-black uppercase bg-yellow-100 text-blue-900 px-3 py-1 rounded-full">{course.grade}</span>
                     </div>
                     <p className="text-sm text-slate-500 leading-relaxed">{course.description}</p>
                   </div>
                 ))}
               </div>
            </div>
          </div>
        )}

        {activeTab === 'announcements' && (
          <div className="grid lg:grid-cols-2 gap-16">
            <div>
              <h3 className="text-2xl font-black text-blue-900 mb-8 font-serif">Post Global Update</h3>
              <form onSubmit={handleAnnSubmit} className="space-y-6 bg-blue-50 p-10 rounded-[2.5rem] border-2 border-blue-100">
                <div className="space-y-2">
                  <label className="text-xs font-black text-blue-900 uppercase tracking-widest px-1">Bulletin Title</label>
                  <input type="text" value={annTitle} required onChange={(e) => setAnnTitle(e.target.value)} className="w-full px-6 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold text-slate-900 outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-blue-900 uppercase tracking-widest px-1">Detailed Content</label>
                  <textarea rows={6} value={annContent} required onChange={(e) => setAnnContent(e.target.value)} className="w-full px-6 py-4 bg-white border-2 border-blue-100 rounded-2xl font-bold text-slate-900 outline-none" />
                </div>
                <button type="submit" className="w-full py-5 bg-blue-900 text-yellow-400 font-black text-lg rounded-2xl shadow-xl hover:bg-blue-800 transition-all">Publish Update</button>
              </form>
            </div>
            <div className="space-y-6">
              <h3 className="text-2xl font-black text-blue-900 font-serif">Communication History</h3>
              <div className="space-y-6 max-h-[600px] overflow-y-auto pr-4 custom-scrollbar">
                {announcements.map(ann => (
                  <div key={ann.id} className="p-8 bg-white border-2 border-slate-100 rounded-[2rem] shadow-sm relative overflow-hidden group hover:border-blue-200 transition-all">
                    <h4 className="font-black text-blue-900 text-xl mb-4 font-serif">{ann.title}</h4>
                    <p className="text-slate-600 text-sm leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                    <p className="text-[10px] font-black text-slate-300 uppercase mt-4">{ann.date}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserRole, AppState, StudentApplication, Announcement, TeacherAccount, StudentResult, Course, GradeLevel, StudentAccount } from './types';
import { stateService } from './services/stateService';
import { Header } from './components/Header';
import { Hero } from './components/Hero';
import { AdminPanel } from './components/AdminPanel';
import { StudentPortal } from './components/StudentPortal';
import { StudentAuth } from './components/StudentAuth';
import { AdminLoginGateway } from './components/AdminLoginGateway';
import { TeacherLoginGateway } from './components/TeacherLoginGateway';
import { Footer } from './components/Footer';
import { TeacherDashboard } from './components/TeacherDashboard';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [state, setState] = useState<AppState>(stateService.getState());
  const [view, setView] = useState<'home' | 'portal' | 'apply' | 'admin' | 'teacherLogin' | 'teacher' | 'studentAuth'>('home');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    stateService.saveState(state);
  }, [state]);

  const updateFees = (grade: string, amount: number) => {
    setState(prev => ({
      ...prev,
      fees: { ...prev.fees, [grade]: amount }
    }));
  };

  const updateCalendar = (content: string) => {
    setState(prev => ({
        ...prev,
        academicCalendar: content
    }));
  };

  const addAnnouncement = (title: string, content: string) => {
    const newAnn: Announcement = {
      id: Date.now().toString(),
      title,
      content,
      date: new Date().toLocaleDateString()
    };
    setState(prev => ({
      ...prev,
      announcements: [newAnn, ...prev.announcements]
    }));
  };

  const addCourse = (name: string, grade: GradeLevel, description: string) => {
    const newCourse: Course = {
      id: 'CRS-' + Date.now(),
      name,
      grade,
      description
    };
    setState(prev => ({
      ...prev,
      courses: [...prev.courses, newCourse]
    }));
  };

  const createStudentAccount = (account: Omit<StudentAccount, 'id' | 'createdAt'>) => {
    if (state.studentAccounts.some(s => s.email === account.email)) {
      setLoginError("An account with this email already exists.");
      return;
    }
    const newAccount: StudentAccount = {
      ...account,
      id: 'STU-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      studentAccounts: [...prev.studentAccounts, newAccount]
    }));
    setRole(UserRole.STUDENT);
    setCurrentUser(newAccount.name);
    setView('portal');
    setLoginError('');
  };

  const handleStudentLogin = (email: string, pass: string) => {
    const student = state.studentAccounts.find(s => s.email === email && s.password === pass);
    if (student) {
      setRole(UserRole.STUDENT);
      setCurrentUser(student.name);
      setView('portal');
      setLoginError('');
    } else {
      setLoginError("Invalid student credentials.");
    }
  };

  const submitApplication = (app: Omit<StudentApplication, 'id' | 'timestamp' | 'paid'>) => {
    const newApp: StudentApplication = {
      ...app,
      id: 'APP-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      paid: true
    };
    setState(prev => ({
      ...prev,
      applications: [newApp, ...prev.applications]
    }));
    return newApp;
  };

  const createTeacherAccount = (teacher: Omit<TeacherAccount, 'id' | 'createdAt'>) => {
    const newTeacher: TeacherAccount = {
      ...teacher,
      id: 'TEA-' + Date.now(),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({
      ...prev,
      teachers: [...prev.teachers, newTeacher]
    }));
  };

  const handleAdminLoginAttempt = (email: string, password: string) => {
    if (email.trim().length > 0 && password === '197005') {
      setRole(UserRole.ADMIN);
      setCurrentUser(email);
      setLoginError('');
      setView('admin');
      return;
    } 
    setLoginError('Invalid admin email or security key.');
  };

  const handleTeacherLoginAttempt = (username: string, password: string) => {
    const teacher = state.teachers.find(t => t.username === username && t.password === password);
    if (teacher) {
      setRole(UserRole.TEACHER);
      setCurrentUser(teacher.username);
      setView('teacher');
      setLoginError('');
      return;
    }
    setLoginError('Incorrect teacher username or password.');
  };

  const handleNav = (v: any) => {
    if ((v === 'apply' || v === 'portal') && role === UserRole.GUEST) {
        setLoginError("You must log in to access admission forms and school fees.");
        setView('studentAuth');
        return;
    }
    setLoginError('');
    setView(v);
  };

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50">
      <Header 
        role={role} 
        setRole={setRole} 
        setView={handleNav} 
        activeView={view} 
      />

      <main className="flex-grow">
        {view === 'home' && (
          <Hero 
            announcements={state.announcements} 
            calendar={state.academicCalendar}
            onApply={() => handleNav('apply')}
          />
        )}

        {view === 'apply' && (
          <div className="max-w-4xl mx-auto py-12 px-4">
            <StudentPortal 
              fees={state.fees} 
              onSubmit={submitApplication} 
              onBack={() => setView('home')} 
            />
          </div>
        )}

        {view === 'studentAuth' && (
          <StudentAuth 
            onLogin={handleStudentLogin}
            onRegister={createStudentAccount}
            onBack={() => setView('home')}
            error={loginError}
          />
        )}

        {view === 'portal' && (
          <div className="max-w-4xl mx-auto py-12 px-4 text-center">
            <div className="bg-white p-12 rounded-2xl shadow-xl border border-yellow-400">
                <h2 className="text-3xl font-black text-blue-900 mb-4 font-serif leading-tight">Welcome Back, <br className="sm:hidden" /> {currentUser}!</h2>
                <p className="text-slate-600 mb-8 font-medium">Access your learning materials and check your results here.</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <button className="p-8 bg-blue-900 text-white rounded-xl hover:bg-blue-800 transition-all flex flex-col items-center group">
                        <span className="block text-4xl mb-2 text-yellow-400 group-hover:scale-110 transition-transform">📚</span>
                        <span className="font-black uppercase text-xs tracking-widest">Active Courses</span>
                    </button>
                    <button 
                        onClick={() => setView('apply')}
                        className="p-8 bg-yellow-400 text-blue-900 rounded-xl hover:bg-yellow-500 transition-all flex flex-col items-center group"
                    >
                        <span className="block text-4xl mb-2 group-hover:scale-110 transition-transform">₦</span>
                        <span className="font-black uppercase text-xs tracking-widest">Pay School Fees</span>
                    </button>
                </div>

                <div className="mt-12 text-left">
                  <h3 className="text-xl font-black text-blue-900 mb-6 font-serif border-b-2 border-slate-50 pb-2">Academic Overview</h3>
                  <div className="grid grid-cols-1 gap-4">
                    {state.courses.map(course => (
                      <div key={course.id} className="p-6 border border-slate-100 rounded-2xl flex justify-between items-center bg-slate-50 hover:bg-white transition-colors group">
                        <div className="max-w-[70%]">
                          <p className="font-black text-blue-900 text-lg group-hover:text-yellow-600 transition-colors">{course.name}</p>
                          <p className="text-xs text-slate-500 font-medium truncate">{course.description}</p>
                        </div>
                        <span className="text-[10px] font-black uppercase bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-nowrap">{course.grade}</span>
                      </div>
                    ))}
                  </div>
                </div>
            </div>
          </div>
        )}

        {view === 'teacherLogin' && (
          <TeacherLoginGateway 
            onLogin={handleTeacherLoginAttempt} 
            onBack={() => setView('home')} 
            error={loginError} 
          />
        )}

        {view === 'teacher' && role === UserRole.TEACHER && (
           <div className="max-w-6xl mx-auto py-12 px-4">
             <TeacherDashboard 
               username={currentUser || 'Staff'} 
               courses={state.courses}
               results={state.results}
               onAddCourse={addCourse}
             />
           </div>
        )}

        {view === 'admin' && (
          role === UserRole.ADMIN ? (
            <div className="max-w-6xl mx-auto py-12 px-4">
              <AdminPanel 
                fees={state.fees} 
                applications={state.applications}
                announcements={state.announcements}
                teachers={state.teachers}
                results={state.results}
                courses={state.courses}
                calendar={state.academicCalendar}
                onUpdateFee={updateFees}
                onAddAnnouncement={addAnnouncement}
                onCreateTeacher={createTeacherAccount}
                onAddCourse={addCourse}
                onUpdateCalendar={updateCalendar}
              />
            </div>
          ) : (
            <AdminLoginGateway 
              onLogin={handleAdminLoginAttempt}
              onBack={() => setView('home')}
              error={loginError}
            />
          )
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;
